using System.Collections.Immutable;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.Diagnostics;
using Relevox.Migration;

namespace Relevox.SourceGenerator.Tests;

/// <summary>
/// RVX0007 and RVX0017 in generated code: reported in a file a person keeps under an <c>&lt;auto-generated&gt;</c>
/// header, never in what a generator or designer writes, which nobody can edit.
/// </summary>
public sealed class MigrationGeneratedCodeTests
{
    private const string Header = """
        // <auto-generated>
        // Written by a tool.
        // </auto-generated>

        """;

    // The shape of Mediator.SourceGenerator's Mediator.g.cs once Mediator.Abstractions is gone: the registration and
    // a handler wrapper naming Mediator's types, which no longer resolve.
    private const string MediatorOutput = Header + """
        namespace Microsoft.Extensions.DependencyInjection
        {
            public static class MediatorDependencyInjectionExtensions
            {
                public static IServiceCollection AddMediator(this IServiceCollection services)
                {
                    services.Add(new ServiceDescriptor(typeof(global::Mediator.IMediator), typeof(object), ServiceLifetime.Singleton));
                    return services;
                }
            }
        }

        namespace Shop.Generated
        {
            public sealed class PingWrapper : global::Mediator.IRequestHandler<global::Shop.Ping, int>
            {
                public global::System.Threading.Tasks.ValueTask<int> Handle(global::Shop.Ping request, global::System.Threading.CancellationToken cancellationToken) => default;
            }
        }
        """;

    private const string MediatROutput = Header + """
        using MediatR;

        namespace Shop.Generated
        {
            public static class Registrations
            {
                public static global::MediatR.Unit Nothing => default;
            }
        }
        """;

    [Fact]
    public async Task RVX0017_is_not_reported_in_what_a_generator_writes()
    {
        ImmutableArray<Diagnostic> diagnostics = await Analyze(
            new MediatorUsageAnalyzer(),
            new Writes("Mediator.g.cs", MediatorOutput),
            ("Ping.cs", "namespace Shop; public sealed record Ping : Relevox.IRequest<int>;"),
            ("Kept.cs", Header + "using Mediator;\nnamespace Shop; public sealed record Pong : IQuery<int>;"),
            ("Forms/Main.Designer.cs", "using Mediator;\nnamespace Shop; public sealed record Pang : IQuery<int>;"));

        Files(diagnostics).ShouldBe(["Kept.cs"]);
    }

    [Fact]
    public async Task RVX0007_is_not_reported_in_what_a_generator_writes()
    {
        ImmutableArray<Diagnostic> diagnostics = await Analyze(
            new MediatRUsageAnalyzer(),
            new Writes("MediatR.g.cs", MediatROutput),
            ("Kept.cs", Header + "using MediatR;\nnamespace Shop; public sealed record Pong : IRequest<int>;"),
            ("Forms/Main.Designer.cs", "using MediatR;\nnamespace Shop; public sealed record Pang : IRequest<int>;"));

        Files(diagnostics).ShouldBe(["Kept.cs"]);
    }

    private static string[] Files(ImmutableArray<Diagnostic> diagnostics) =>
        [.. diagnostics.Select(static diagnostic => System.IO.Path.GetFileName(diagnostic.Location.SourceTree!.FilePath)).Distinct()];

    // The sources compiled, the generator run as the build runs it, then the analyzer over everything, generated
    // trees included, as the IDE and dotnet format see them.
    private static async Task<ImmutableArray<Diagnostic>> Analyze(DiagnosticAnalyzer analyzer, IIncrementalGenerator generator, params (string Path, string Source)[] sources)
    {
        CSharpParseOptions parse = new(LanguageVersion.Preview);
        CSharpCompilation compilation = CSharpCompilation.Create(
            "Shop",
            sources.Select(source => CSharpSyntaxTree.ParseText(source.Source, parse, source.Path)),
            GeneratorHarness.References,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        CSharpGeneratorDriver
            .Create([generator.AsSourceGenerator()], parseOptions: parse)
            .RunGeneratorsAndUpdateCompilation(compilation, out Compilation output, out _);
        output.SyntaxTrees.Count().ShouldBe(sources.Length + 1);

        return await output.WithAnalyzers([analyzer]).GetAnalyzerDiagnosticsAsync();
    }

    /// <summary>A generator that writes one fixed file, standing in for Mediator's or any other.</summary>
    private sealed class Writes(string hintName, string source) : IIncrementalGenerator
    {
        public void Initialize(IncrementalGeneratorInitializationContext context) =>
            context.RegisterPostInitializationOutput(output => output.AddSource(hintName, source));
    }
}
